```gq
// GQ queries cannot call other queries, so this one inlines the colleagues pattern twice
// instead of reusing `colleagues`. The caller reads the distinct names directly.
query colleagues_of_colleagues($of: String) {
    match {
        $p: Person { handle: $of }
        $p worksAt $c1
        $m worksAt $c1
        $m.handle != $of
        $m worksAt $c2
        $n worksAt $c2
        $n.handle != $m.handle
    }
    return distinct { $n.name }
}
